import sys
import heapq

def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m = readints()
    queries = [readints() for _ in range(m)]

    # Initialize the array with -1 (indicating unassigned)
    a = [-1] * n

    # Priority queue to store subarrays by their mex
    pq = []

    # Initialize the mex for each subarray
    for l, r in queries:
        mex = 0
        while mex in set(a[l-1:r]):
            mex += 1
        heapq.heappush(pq, (mex, l, r))

    # Process the subarrays
    while pq:
        mex, l, r = heapq.heappop(pq)

        # Assign the mex value to the first unassigned position in the subarray
        for i in range(l-1, r):
            if a[i] == -1:
                a[i] = mex
                break

        # Update the mex for other subarrays that include this position
        for l2, r2 in queries:
            if l <= l2 <= r or l <= r2 <= r or l2 <= l <= r2:
                new_mex = 0
                while new_mex in set(a[l2-1:r2]):
                    new_mex += 1
                heapq.heappush(pq, (new_mex, l2, r2))

    # Find the minimum mex among all subarrays
    min_mex = float('inf')
    for l, r in queries:
        mex = 0
        while mex in set(a[l-1:r]):
            mex += 1
        min_mex = min(min_mex, mex)

    # Print the result
    print(min_mex)
    print(' '.join(map(str, a)))

if __name__ == "__main__":
    main()
